override fun onCreate(state: Bundle?) {
    super.onCreate(state)
    setContent { QuestApp() }
}

fun initials(name: String?): String =
    name?.trim()?.takeIf { it.isNotEmpty() }
        ?.take(2)?.uppercase() ?: "DQ"

sealed interface LoadResult {
    data class Ready(val title: String): LoadResult
    data class Failed(val cause: String): LoadResult
    data object Loading: LoadResult
}

suspend fun loadBoth() = coroutineScope {
    val user = async { loadUser() }
    val lessons = async { loadLessons() }
    user.await() to lessons.await()
}

suspend fun scan(items: List<String>) {
    for (item in items) {
        currentCoroutineContext().ensureActive()
        inspect(item)
    }
}

@Composable
fun Counter(value: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) { Text("$value") }
}

val sorted = remember(items) { items.sorted() }
LazyColumn {
    items(sorted, key = { it.id }) { ItemRow(it) }
}

LaunchedEffect(lessonId) {
    viewModel.load(lessonId)
}
DisposableEffect(owner) {
    owner.addListener(listener)
    onDispose { owner.removeListener(listener) }
}

interface LessonRepository {
    fun observe(): Flow<List<Lesson>>
    suspend fun complete(id: String)
}

fun onAction(action: Action) {
    when (action) {
        is Action.Complete -> viewModelScope.launch {
            completeLesson(action.id)
        }
    }
}

sealed interface FetchResult {
    data class Data(val body: String): FetchResult
    data class HttpError(val status: Int): FetchResult
    data class Offline(val cause: IOException): FetchResult
}

class LoadLessons @Inject constructor(
    private val repository: LessonRepository
) {
    operator fun invoke() = repository.observe()
}

db.withTransaction {
    dao.complete(lessonId)
    dao.insertReward(
        Reward("lesson:$lessonId", 20)
    ) // unique key, ignore duplicates
}

fun observeLessons(): Flow<List<Lesson>> =
    dao.observeLessons()
suspend fun refresh() {
    val remote = api.lessons()
    db.withTransaction { dao.upsert(remote) }
}

@Test fun emitsResult() = runTest {
    val values = mutableListOf<Int>()
    backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
        repository.count.collect { values += it }
    }
    repository.increment()
    assertEquals(1, values.last())
}

